utation_source_full_v1(jsonb,uuid,text)","argNames":["p","gid","fy"],"result":"jsonb","language":"plpgsql","defaults":0,"config":["search_path=pg_catalog, public, pg_temp","TimeZone=UTC"],"runtime":true,"bodySha256":"62b8da5b0664cdba3870cfaeccbc50ad1c7719046af9c32246fc97edc2a9cacb","definitionSha256":"e02320286281270a65b572f8b91619825da23fa69cb39fc4b19c4172ade229c5","volatility":"v","defaultExpressions":""},{"name":"own_imputation_detail_full_v1","signature":"public.own_imputation_detail_full_v1(jsonb,uuid)","argNames":["p","pid"],"result":"jsonb","language":"plpgsql","defaults":0,"config":["search_path=pg_catalog, public, pg_temp","TimeZone=UTC"],"runtime":true,"bodySha256":"0d5bd247201a808668be817962521cec714e1840121ea87a4a5225db9da2be81","definitionSha256":"28d23d575cb418ffa21d665dbf20771a4858d4c5b5b7624b45722b1c56eebee0","volatility":"v","defaultExpressions":""},{"name":"own_imputation_command_full_v1","signature":"public.own_imputation_command_full_v1(jsonb,jsonb,uuid)","argNames":["p","body_value","key"],"result":"jsonb","language":"plpgsql","defaults":0,"config":["search_path=pg_catalog, public, pg_temp","TimeZone=UTC"],"runtime":true,"bodySha256":"71fe2080017eb037bf554d1212b0ae8ff1e3b8849c8ecd058b6d937ad40cd1cd","definitionSha256":"e2e2538fb84eb34c54fe8f0d5c1168958d36b62ebff7d2b2e063ba9817ac4a34","volatility":"v","defaultExpressions":""}]'::jsonb) LOOP
  SELECT * INTO actual FROM pg_proc WHERE oid=to_regprocedure(expected->>'signature');
  IF actual.oid IS NULL OR actual.proowner<>current_user::regrole OR actual.prokind<>'f' OR NOT actual.prosecdef OR actual.proretset OR actual.proisstrict OR actual.proleakproof OR actual.proparallel<>'u'
   OR actual.provolatile IS DISTINCT FROM(expected->>'volatility')::"char" OR actual.procost<>100 OR actual.prorows<>0 OR actual.prosupport<>0 OR actual.probin IS NOT NULL OR actual.proallargtypes IS NOT NULL OR actual.provariadic<>0
   OR actual.prorettype IS DISTINCT FROM to_regtype(expected->>'result') OR actual.prolang IS DISTINCT FROM(SELECT oid FROM pg_language WHERE lanname=expected->>'language') OR actual.pronargdefaults<>(expected->>'defaults')::integer OR coalesce(pg_get_expr(actual.proargdefaults,0),'') IS DISTINCT FROM expected->>'defaultExpressions' OR actual.proargmodes IS NOT NULL OR actual.prosqlbody IS NOT NULL
   OR coalesce(to_jsonb(actual.proargnames),'null'::jsonb) IS DISTINCT FROM expected->'argNames' OR to_jsonb(actual.proconfig) IS DISTINCT FROM expected->'config'
   OR encode(sha256(convert_to(replace(actual.prosrc,E'\r\n',E'\n'),'UTF8')),'hex')<>expected->>'bodySha256'
   OR(SELECT count(*) FROM pg_proc p WHERE p.pronamespace='public'::regnamespace AND p.proname=expected->>'name')<>1
  THEN RAISE EXCEPTION 'IMPUTATION_CAPACITY_SOURCE_CHANGED';END IF;
  IF EXISTS(SELECT 1 FROM aclexplode(coalesce(actual.proacl,acldefault('f',actual.proowner))) a WHERE a.grantor<>actual.proowner OR a.privilege_type<>'EXECUTE' OR a.is_grantable OR(a.grantee<>actual.proowner AND NOT((expected->>'runtime')::boolean AND a.grantee=runtime_oid)))
   OR NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(actual.proacl,acldefault('f',actual.proowner))) a WHERE a.grantee=actual.proowner AND a.privilege_type='EXECUTE' AND NOT a.is_grantable)
   OR (expected->>'runtime')::boolean IS DISTINCT FROM EXISTS(SELECT 1 FROM aclexplode(coalesce(actual.proacl,acldefault('f',actual.proowner))) a WHERE a.grantee=runtime_oid AND a.privilege_type='EXECUTE' AND NOT a.is_grantable)
   OR(SELECT count(*) FROM aclexplode(coalesce(actual.proacl,acldefault('f',actual.proowner))))<>(CASE WHEN(expected->>'runtime')::boolean THEN 2 ELSE 1 END)
  THEN RAISE EXCEPTION 'IMPUTATION_CAPACITY_ACL_CHANGED';END IF;
 END LOOP;
 FOR prior IN SELECT value FROM jsonb_array_elements(original_functions) LOOP
  SELECT * INTO actual FROM pg_proc WHERE oid=(prior->>'oid')::oid;
  IF actual.oid IS NULL OR(actual.proname IN('own_imputation_source_v1','own_imputation_detail_v1','own_imputation_command_v1') AND (to_jsonb(actual)-'prosrc') IS DISTINCT FROM(prior-'prosrc'))
   OR(actual.proname NOT IN('own_imputation_source_v1','own_imputation_detail_v1','own_imputation_command_v1') AND to_jsonb(actual) IS DISTINCT FROM prior)
  THEN RAISE EXCEPTION 'IMPUTATION_CAPACITY_ORIGINAL_METADATA_CHANGED';END IF;
 END LOOP;
 IF(SELECT count(*) FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname LIKE 'own_imputation_%')<>17 THEN RAISE EXCEPTION 'IMPUTATION_CAPACITY_OBJECT_CONFLICT';END IF;
 SELECT * INTO checked_constraint FROM pg_constraint WHERE conrelid=target_relation AND conname='own_payroll_imputation_event_allocation_check';
 IF checked_constraint.oid IS NULL OR checked_constraint.contype<>'c' OR NOT checked_constraint.convalidated OR NOT checked_constraint.conislocal OR checked_constraint.coninhcount<>0 OR checked_constraint.connoinherit OR checked_constraint.condeferrable OR checked_constraint.condeferred
  OR pg_get_expr(checked_constraint.conbin,checked_constraint.conrelid,false) IS DISTINCT FROM '((jsonb_typeof(allocation) = ANY (ARRAY[''object''::text, ''null''::text])) AND (octet_length((allocation)::text) <= 33554432))' THEN RAISE EXCEPTION 'IMPUTATION_CAPACITY_CHECK_CHANGED';END IF;
 SELECT * INTO checked_constraint FROM pg_constraint WHERE conrelid=target_relation AND conname='own_payroll_imputation_event_source_snapshot_check';
 IF checked_constraint.oid IS NULL OR checked_constraint.contype<>'c' OR NOT checked_constraint.convalidated OR NOT checked_constraint.conislocal OR checked_constraint.coninhcount<>0 OR checked_constraint.connoinherit OR checked_constraint.condeferrable OR checked_constraint.condeferred
  OR pg_get_expr(checked_constraint.conbin,checked_constraint.conrelid,false) IS DISTINCT FROM '((jsonb_typeof(source_snapshot) = ANY (ARRAY[''object''::text, ''null''::text])) AND (octet_length((source_snapshot)::text) <= 16777216))' THEN RAISE EXCEPTION 'IMPUTATION_CAPACITY_CHECK_CHANGED';END IF;
 SELECT * INTO checked_constraint FROM pg_constraint WHERE conrelid=target_relation AND conname='own_payroll_imputation_event_body_check';
 IF checked_constraint.oid IS NULL OR checked_constraint.contype<>'c' OR NOT checked_constraint.convalidated OR NOT checked_constraint.conislocal OR checked_constraint.coninhcount<>0 OR checked_constraint.connoinherit OR checked_constraint.condeferrable OR checked_constraint.condeferred
  OR pg_get_expr(checked_constraint.conbin,checked_constraint.conrelid,false) IS DISTINCT FROM '((jsonb_typeof(body) = ''object''::text) AND (octet_length((body)::text) <= 32768))' THEN RAISE EXCEPTION 'IMPUTATION_CAPACITY_CHECK_CHANGED';END IF;
 SELECT to_jsonb(t) INTO table_after FROM pg_class t WHERE t.oid=target_relation;
 IF table_after IS DISTINCT FROM table_before OR columns_before IS DISTINCT FROM(SELECT coalesce(jsonb_agg(to_jsonb(a) ORDER BY a.attnum),'[]') FROM pg_attribute a WHERE a.attrelid=target_relation)
  OR constraints_before IS DISTINCT FROM(SELECT coalesce(jsonb_agg(to_jsonb(c) ORDER BY c.oid),'[]') FROM pg_constraint c WHERE c.conrelid=target_relation AND c.conname<>'own_payroll_imputation_event_allocation_check')
 THEN RAISE EXCEPTION 'IMPUTATION_CAPACITY_TABLE_METADATA_CHANGED';END IF;
END $imputation_capacity_203$;
